import java.util.*;

class Solution {
    public int[] smallestRange(List<List<Integer>> nums) {
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] - b[0]);
        int curMax = Integer.MIN_VALUE;
        for (int i = 0; i < nums.size(); i++) {
            int val = nums.get(i).get(0);
            pq.offer(new int[]{val, i, 0});
            curMax = Math.max(curMax, val);
        }
        int[] result = {pq.peek()[0], curMax};
        while (true) {
            int[] min = pq.poll();
            int listIdx = min[1], elemIdx = min[2];
            if (elemIdx + 1 >= nums.get(listIdx).size()) break;
            int next = nums.get(listIdx).get(elemIdx + 1);
            pq.offer(new int[]{next, listIdx, elemIdx + 1});
            curMax = Math.max(curMax, next);
            if (curMax - pq.peek()[0] < result[1] - result[0]) {
                result[0] = pq.peek()[0];
                result[1] = curMax;
            }
        }
        return result;
    }
}
